diff --git a/src/lib/OpenEXR/ImfIDManifest.cpp b/src/lib/OpenEXR/ImfIDManifest.cpp
index 4a41f27c..f89005dc 100644
--- a/src/lib/OpenEXR/ImfIDManifest.cpp
+++ b/src/lib/OpenEXR/ImfIDManifest.cpp
@@ -405,7 +405,7 @@ IDManifest::init (const char* data, const char* endOfData)
     // comments in serialize function describe the format
     //

-    vector<int> mapping (stringList.size ());
+    vector<int> mapping;

     //
     // overlapping sequences: A list [(4,5),(3,6)] expands to 4,5,3,6 - because 4 and 5 are including already
@@ -423,7 +423,6 @@ IDManifest::init (const char* data, const char* endOfData)

     Xdr::read<CharPtrIO> (data, rleLength);

-    int currentIndex = 0;
     for (int i = 0; i < rleLength; ++i)
     {
         int first;
@@ -447,9 +446,8 @@ IDManifest::init (const char* data, const char* endOfData)
             // don't remap already mapped values
             if (seen[entry] == 0)
             {
-                mapping[currentIndex] = entry;
+                mapping.push_back (entry);
                 seen[entry]           = 1;
-                currentIndex++;
             }
         }
     }
@@ -571,7 +569,7 @@ IDManifest::init (const char* data, const char* endOfData)
                     throw IEX_NAMESPACE::InputExc (
                         "Bad string index in IDManifest");
                 }
-                (insertion.first)->second[i] = stringList[mapping[stringIndex]];
+                (insertion.first)->second[i] = stringList[mapping.at (stringIndex)];
             }
         }
     }

diff --git a/src/lib/OpenEXR/ImfIDManifest.cpp b/src/lib/OpenEXR/ImfIDManifest.cpp
